local HelmetCrestMaker = {}
local PRODUCTS = {
    iron_helmetcrest = { name = "Železni čeladni greben", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni čeladni greben za čelade." },
    bronze_helmetcrest = { name = "Bronast čeladni greben", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast čeladni greben za čelade." },
    silver_helmetcrest = { name = "Srebrn čeladni greben", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn čeladni greben za čelade." },
    gilded_helmetcrest = { name = "Pozlačen čeladni greben", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen čeladni greben za čelade." },
    jewel_set_helmetcrest = { name = "Draguljast čeladni greben", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast čeladni greben za čelade." },
    royal_sovereign_helmetcrest = { name = "Kraljevski suveren čeladni greben", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren čeladni greben z biseri za krono." },
}
local BUILDINGS = {
    helmetcrest_workshop = { name = "Helmetcrest delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    helmetcrest_house = { name = "Helmetcrest hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_helmetcrest_atelier = { name = "Mojstrski helmetcrest atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_helmetcrest_palace = { name = "Suverena helmetcrest palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HelmetCrestMaker.ironStock = 10; HelmetCrestMaker.bronzeStock = 8; HelmetCrestMaker.woodStock = 16; HelmetCrestMaker.leatherStock = 14; HelmetCrestMaker.silverStock = 8; HelmetCrestMaker.goldStock = 6; HelmetCrestMaker.jewelStock = 4; HelmetCrestMaker.pearlStock = 4
HelmetCrestMaker.productStock = {}; HelmetCrestMaker.buildings = {}; HelmetCrestMaker.maker = nil; HelmetCrestMaker.activeMaking = {}; HelmetCrestMaker.totalProducts = 0; HelmetCrestMaker.dayTimer = 0
function HelmetCrestMaker.init() HelmetCrestMaker.ironStock=10; HelmetCrestMaker.bronzeStock=8; HelmetCrestMaker.woodStock=16; HelmetCrestMaker.leatherStock=14; HelmetCrestMaker.silverStock=8; HelmetCrestMaker.goldStock=6; HelmetCrestMaker.jewelStock=4; HelmetCrestMaker.pearlStock=4; HelmetCrestMaker.productStock={}; HelmetCrestMaker.buildings={}; HelmetCrestMaker.maker=nil; HelmetCrestMaker.activeMaking={}; HelmetCrestMaker.totalProducts=0; HelmetCrestMaker.dayTimer=0; print("[HelmetCrestMaker] Royal Helmet Crest Maker System initialized (6 products, 4 buildings)") end
function HelmetCrestMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HelmetCrestMaker.maker={name=n or ("Grenar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Grenar najet: %s (spretnost: %d)",HelmetCrestMaker.maker.name,s),"success") end; return true end
function HelmetCrestMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HelmetCrestMaker.build(id) local ok,e=HelmetCrestMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HelmetCrestMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HelmetCrestMaker.getQualityBonus() local b=0; for _,bd in ipairs(HelmetCrestMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HelmetCrestMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HelmetCrestMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HelmetCrestMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HelmetCrestMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HelmetCrestMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HelmetCrestMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HelmetCrestMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HelmetCrestMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HelmetCrestMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HelmetCrestMaker.buildings==0 then return false,"Potrebna grenska delavnica" end; if not HelmetCrestMaker.maker then return false,"Potreben grenar" end; return true end
function HelmetCrestMaker.make(pt,qty) qty=qty or 1; local ok,e=HelmetCrestMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HelmetCrestMaker.ironStock=HelmetCrestMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HelmetCrestMaker.bronzeStock=HelmetCrestMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HelmetCrestMaker.woodStock=HelmetCrestMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HelmetCrestMaker.leatherStock=HelmetCrestMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HelmetCrestMaker.silverStock=HelmetCrestMaker.silverStock-d.silverCost*qty end; if d.goldCost then HelmetCrestMaker.goldStock=HelmetCrestMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HelmetCrestMaker.jewelStock=HelmetCrestMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HelmetCrestMaker.pearlStock=HelmetCrestMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HelmetCrestMaker.maker then t=math.max(1,t-math.floor(HelmetCrestMaker.maker.skill/13)) end; table.insert(HelmetCrestMaker.activeMaking,{id="helmetcrest_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HelmetCrestMaker.completeMaking(m) local q=1.0+(HelmetCrestMaker.getQualityBonus()/100); if HelmetCrestMaker.maker then q=q+(HelmetCrestMaker.maker.skill/140) end; q=math.min(2.5,q); HelmetCrestMaker.productStock[m.productType]=(HelmetCrestMaker.productStock[m.productType] or 0)+m.quantity; HelmetCrestMaker.totalProducts=HelmetCrestMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HelmetCrestMaker.maker then HelmetCrestMaker.maker.itemsMade=HelmetCrestMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HelmetCrestMaker.maker.skill=math.min(100,HelmetCrestMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Greben izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"helmetcrest.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HelmetCrestMaker.update(dt) if not _G.state then return end; HelmetCrestMaker.dayTimer=HelmetCrestMaker.dayTimer+dt; if HelmetCrestMaker.dayTimer>=30 then HelmetCrestMaker.dayTimer=0; for i=#HelmetCrestMaker.activeMaking,1,-1 do local m=HelmetCrestMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HelmetCrestMaker.completeMaking(m); table.remove(HelmetCrestMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HelmetCrestMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HelmetCrestMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HelmetCrestMaker.getStats() return {ironStock=HelmetCrestMaker.ironStock,bronzeStock=HelmetCrestMaker.bronzeStock,woodStock=HelmetCrestMaker.woodStock,leatherStock=HelmetCrestMaker.leatherStock,silverStock=HelmetCrestMaker.silverStock,goldStock=HelmetCrestMaker.goldStock,jewelStock=HelmetCrestMaker.jewelStock,pearlStock=HelmetCrestMaker.pearlStock,productStock=HelmetCrestMaker.productStock,numBuildings=#HelmetCrestMaker.buildings,hasMaker=HelmetCrestMaker.maker~=nil,makerName=HelmetCrestMaker.maker and HelmetCrestMaker.maker.name or "—",makerSkill=HelmetCrestMaker.maker and HelmetCrestMaker.maker.skill or 0,activeMaking=#HelmetCrestMaker.activeMaking,totalProducts=HelmetCrestMaker.totalProducts} end
return HelmetCrestMaker
